/**
 * REPORT FLAG LIBRARY (Chapters 1, 3, 5, 8), the standardized risk paragraphs extracted +
 * deduped from the 16 Trellis-styled ODD reports, completing the engine's reusable risk
 * language across all eight chapters. Chapter 4's library lives in ch4-flag-library.ts.
 *
 * Same shape as the Ch4 library: title + plain-English trigger + severity + verbatim text.
 * Generation drops in the verbatim text for whichever flags fire; the model never writes it.
 *
 * Counts (distinct): Ch1 25 · Ch2 21 · Ch3 6 · Ch5 7 · Ch6 7 · Ch7 11 · Ch8 7 (= 84 here;
 * 51 more in ch4-flag-library → ~135 total across the report).
 */

export type ReportFlag = {
 id: string;
 chapter: number;
 title: string;
 trigger: string;
 severity: "red" | "amber" | "watch";
 text: string;
};

export const REPORT_FLAGS: ReportFlag[] = [
 // ── Chapter 1 · Manager, Ownership & Governance ──────────────────────────
 { id: "c1-sma", chapter: 1, title: "Manager runs separately managed accounts (\"SMA\").", trigger: "Manager operates one or more SMAs / single-investor vehicles", severity: "watch",
 text: "Manager runs separately managed accounts (\"SMA\"). Use of separately managed account structures is common within certain alternative asset strategies. While impacted by trading volumes and overall complexity, use of SMAs, particularly when there are multiple accounts involved, can increase operational complexity for the asset manager: fair trade allocation between accounts; systems complexity to track multiple portfolios; and operational challenges if different accounts use different prime brokers, custodians, administrators or other service providers." },
 { id: "c1-sma-diff-sp", chapter: 1, title: "Separately managed account(s) have different service provider relationships as compared to reference fund product(s).", trigger: "SMAs use different service providers than the flagship fund", severity: "amber",
 text: "Separately managed account(s) have different service provider relationships as compared to reference fund product(s). Managed account structures can increase operational risk should investor-created SMAs use different service providers as compared to the \"flagship\" fund. Each service provider will typically have different systems, reporting formats and data feeds; a manager may need to invest disproportionately in their own operational infrastructure to support a parallel SMA. Risk increases if an SMA investor imposes less effective service providers, distracting back office staff from the flagship fund." },
 { id: "c1-concentration-firm", chapter: 1, title: "Material investor concentration - Firm level.", trigger: "Largest / top-five investor > 25% / 50% of firm AUM", severity: "amber",
 text: "Material investor concentration - Firm level. This situation creates a risk of financial dependency on a single or small group of investor(s): if such investor(s) were to redeem, the Manager may be required to restructure and scale back its activities, and in some situations the firm as a whole may become financially unviable and be forced to close. Alpine flags concentration at the firm level when the largest and / or top five investor relationships represent more than 25% and 50%, respectively, of overall assets under management." },
 { id: "c1-aum-up-25", chapter: 1, title: "Manager AUM has increased (minimum 25% over the past twelve months).", trigger: "Firm AUM grew ≥ 25% YoY", severity: "watch",
 text: "Manager AUM has increased (minimum 25% over the past twelve months). Increases in AUM demonstrate the success of the management company. We note, however, that rapid growth can create operational and organizational stress, particularly if accompanied by the launch of new funds and accounts. We strongly prefer to see increased revenue demonstrably reinvested in the management company through hires of more staff, improved systems etc." },
 { id: "c1-insider-2pct", chapter: 1, title: "Insider investment is less than 2% of firm wide AUM.", trigger: "Insider / GP commitment < 2% of firmwide committed capital (PE)", severity: "amber",
 text: "Insider investment is less than 2% of firm wide AUM. It is typically preferred for executives to invest a material amount of their personal net worth alongside investors so that internal staff \"eat their own cooking\". Within private equity, short-term risk-taking is mitigated by the closed-ended structure; in this context Alpine flags managers where insider investment (generally GP commitments) is less than 2% of firmwide committed capital. GP commitments made through cash contributions create higher alignment than those made through the waiver of management fees." },
 { id: "c1-insider-5pct", chapter: 1, title: "Insider investment is less than 5% of firm wide AUM.", trigger: "Insider investment < 5% of firmwide AUM (open-ended)", severity: "amber",
 text: "Insider investment is less than 5% of firm wide AUM. It is typically preferred for executives to invest a material amount of their personal net worth alongside investors so that internal staff \"eat their own cooking\". Alpine flags all asset managers where insider investment is less than 5% of firmwide assets under management." },
 { id: "c1-insider-50pct-nw", chapter: 1, title: "Insider capital does not represent over 50% of the liquid net worth of the Principal(s).", trigger: "Insider capital < 50% of principals' liquid net worth", severity: "amber",
 text: "Insider capital does not represent over 50% of the liquid net worth of the Principal(s). A typical industry measure is that at least 50% of the liquid net worth of the Principal(s) should be invested in the firm's products (excluding a primary residence). The significance is impacted by operating history: we would strongly expect a manager with a long, profitable track record to have 50% (or significantly more) of liquid net worth at risk in the firm's strategies." },
 { id: "c1-external-investor", chapter: 1, title: "Manager has external investor(s).", trigger: "Part of the management-company equity held by external investors", severity: "watch",
 text: "Manager has external investor(s). Situations where a proportion of equity is owned by external investors (friends and family, business associates, seeding platforms, private equity firms) can raise diligence issues. Diligence will consider whether the external investor has a controlling interest, whether a minority investor is passive or active, and whether the relationship creates potential conflicts of interest." },
 { id: "c1-controlling-individual", chapter: 1, title: "Key person risk: individual holds a controlling equity interest in the firm.", trigger: "A single individual holds majority / controlling equity", severity: "amber",
 text: "Key person risk: individual holds a controlling equity interest in the firm. Over time, we would expect the founder to disburse equity ownership to other key professionals to ensure a more diversified, \"institutional\" ownership structure. Majority ownership can indicate material key person risk and, over time, succession-planning issues should the founder retire or withdraw from the business." },
 { id: "c1-ownership-undisclosed", chapter: 1, title: "Ownership structure is not disclosed / specific ownership percentages not provided.", trigger: "Manager did not disclose ownership structure / percentages", severity: "amber",
 text: "Ownership structure is not disclosed / specific ownership percentages not provided. Ownership information is material to understand whether there is a key person, external investors, and / or potential conflicts of interest. Alpine flags situations in which information as to the ownership structure was not made available during the due diligence process." },
 { id: "c1-consultants", chapter: 1, title: "Manager retains third party consultants.", trigger: "Manager uses third-party consultants alongside FTEs", severity: "watch",
 text: "Manager retains third party consultants. Diligence should consider the duration of the consultant relationship (permanent or temporary); whether consultants act exclusively for the manager or have other clients (and any resulting conflicts); and whether consultants are subject to binding contracts covering confidentiality and adherence to Manager cybersecurity policies." },
 { id: "c1-short-history", chapter: 1, title: "Manager has a short operating history (< 3 years).", trigger: "Firm track record under ~3 years", severity: "amber",
 text: "Manager has a short operating history (< 3 years). Operational and accounting workflow may require ongoing development as the firm gains experience. Systems may not be fully tested; the firm may not yet be financially viable; and initial personnel may prove misaligned with the needs of the business, leading to turnover during the initial period of operations." },
 { id: "c1-related-bd", chapter: 1, title: "Manager has a related party broker-dealer.", trigger: "A broker-dealer operates within the manager's group", severity: "amber",
 text: "Manager has a related party broker-dealer. If a broker-dealer is used for trade execution, diligence should consider the rationale, instruments traded, and volumes passed through it. A broker-dealer which is a material profit center (even if commissions are stated as arms-length) should be subject to detailed diligence; in extreme cases a manager may undertake unnecessary portfolio churning solely to generate commissions." },
 { id: "c1-regulated-products", chapter: 1, title: "Manager offers regulated product structures (40 Act, UCITS etc.).", trigger: "Manager offers products in regulated formats", severity: "watch",
 text: "Manager offers regulated product structures (40 Act, UCITS etc.). Such products mandate a significantly more demanding legal, regulatory and compliance framework than private funds. For small managers, the associated issues can be disproportionately impactful on internal resources; asset owners should expect appropriately resourced compliance and legal capability." },
 { id: "c1-public-manager", chapter: 1, title: "Manager is publicly traded.", trigger: "The manager (or parent) is publicly listed", severity: "watch",
 text: "Manager is publicly traded. A public listing can provide helpful additional diligence information (management-company financials) and an enhanced control environment (Sarbanes-Oxley, internal audit). We highlight, however, the complexity of public-company reporting, and that the stock price is directly related to profitability, indicating potential tendencies to increase fees and focus on asset gathering." },
 { id: "c1-headcount-10", chapter: 1, title: "Headcount of fewer than 10.", trigger: "Firm headcount < 10 professionals", severity: "amber",
 text: "Headcount of fewer than 10. In such environments it is more likely to encounter segregation-of-duties issues (traders also handling back office tasks) and back office executives assuming multiple roles. We are more concerned where a manager with larger AUM (and fee income) has nonetheless elected not to add additional professionals, which can indicate a firm unduly controlled by the founding principal." },
 { id: "c1-no-coo-cfo", chapter: 1, title: "Manager does not have a designated COO or CFO.", trigger: "No designated COO or CFO", severity: "red",
 text: "Manager does not have a designated COO or CFO. A management company which has not appointed a designated CFO or COO displays materially elevated operational risk: there is no \"C\"-level executive appointed to take subject-matter responsibility for back office and business-management tasks and to ensure those decisions are segregated from front-office investment professionals." },
 { id: "c1-shared-office", chapter: 1, title: "Office space shared with unaffiliated third party.", trigger: "Manager shares office space with an unaffiliated party", severity: "watch",
 text: "Office space shared with unaffiliated third party. The rationale should be considered (short-term lease or permanent facility). Physical security and data confidentiality may be material: is the manager's space physically secured, or do staff work in an unsecured / open-plan area? Shared IT facilities (e.g. server rooms) may also raise operational risk." },
 { id: "c1-below-breakeven", chapter: 1, title: "Firm is operating at or below breakeven AUM.", trigger: "Current AUM at / below stated breakeven", severity: "amber",
 text: "Firm is operating at or below breakeven AUM. A manager with AUM at or below breakeven may indicate a material operational risk; ability to continue as a going concern typically depends on the founding partners' ability to provide working capital to sustain the business." },
 { id: "c1-no-succession", chapter: 1, title: "No formal succession plan.", trigger: "No formal / written succession plan", severity: "amber",
 text: "No formal succession plan. A succession plan indicates operational and business-management maturity: it outlines how founding executives' responsibilities and ownership may transfer to other employees, and considers unintended succession due to death or incapacity. We recognize that young organizations may not yet consider succession material." },
 { id: "c1-no-keyman-insurance", chapter: 1, title: "No key person life insurance.", trigger: "No key-person life insurance on founder / key execs", severity: "watch",
 text: "No key person life insurance. Best practice suggests a life insurance policy on the founding partner and / or key executives. Such a policy can allow restructuring of management-company equity (buy-out of the estate) and provide capital to increase the likelihood the management company can continue operations." },
 { id: "c1-c-level-turnover", chapter: 1, title: "Turnover of C-level executive(s) and / or Principal(s).", trigger: "Turnover among senior staff / principals", severity: "amber",
 text: "Turnover of C-level executive(s) and / or Principal(s). Diligence will consider the explanation for the departure(s); whether planned; whether resignation or termination; whether departures led to client withdrawals or litigation. Multiple examples of turnover within a short period can indicate managerial, cultural or financial-viability issues." },
 { id: "c1-no-deferred-comp", chapter: 1, title: "No mandatory deferred compensation scheme.", trigger: "No mandatory deferred-compensation scheme", severity: "watch",
 text: "No mandatory deferred compensation scheme. A deferred compensation scheme ensures a portion of variable compensation remains at risk on a forward-looking basis (typically 3 years), so that portfolio managers are not incented to take unnecessary risk to lock in bonus compensation over a single year." },
 { id: "c1-single-bo", chapter: 1, title: "Limited internal resources - single back office / operations professional.", trigger: "A single professional handles all back-office duties", severity: "amber",
 text: "Limited internal resources - single back office / operations professional. We highlight that (1) segregation of duties may be compromised during vacation / illness; (2) significant operational knowledge may be lost if the sole back-office professional leaves; and (3) the firm is materially exposed to the competence of that single staff member." },
 { id: "c1-nepotism", chapter: 1, title: "Employees are related / married within the firm.", trigger: "Family / marital relationships between employees", severity: "watch",
 text: "Employees are related / married within the firm. Nepotism can be a material diligence issue. Circumstances where a Manager has appointed family members who do not have prior experience or credentials supporting their roles can create material due diligence issues." },

 // ── Chapter 2 · Legal, Regulatory & Compliance ───────────────────────────
 { id: "c2-nonroutine-reg", chapter: 2, title: "Manager, affiliate or employee has been subject to non-routine correspondence or inquiry from a regulatory agency.", trigger: "Non-routine regulatory correspondence / inquiry", severity: "amber",
 text: "Manager, affiliate or employee has been subject to non-routine correspondence or inquiry from a regulatory agency. Investors should request further information as to the nature of unusual regulatory engagement. A manager who feels claims are without merit will likely be fulsome with explanations; a manager who rapidly resorts to a position that information is not available is, in Alpine's experience, more likely to subsequently be exposed to a negative regulatory event." },
 { id: "c2-sanction-10yr", chapter: 2, title: "Manager, affiliate or employee has been subject to regulatory sanction(s) in the past ten years.", trigger: "Regulatory sanction within past 10 years", severity: "amber",
 text: "Manager, affiliate or employee has been subject to regulatory sanction(s) in the past ten years. Investors should request a full description of the facts. Some sanctions may be \"housekeeping\" items, but more pervasive sanctions may materially impact the decision as to whether the manager is a reliable fiduciary. Alpine highlights situations in which a management company has settled \"without admitting or denying\" responsibility." },
 { id: "c2-never-inspected", chapter: 2, title: "Manager has never been subject to a regulatory inspection.", trigger: "Compliance environment never inspected by any regulator", severity: "amber",
 text: "Manager has never been subject to a regulatory inspection. The manager's regulatory controls, procedures and disclosures have not been reviewed by the regulator, and may be found deficient in the event of an eventual inspection. Risks are particularly elevated if the Manager displays other compliance weaknesses (no CCO, no capable external consultant, no recognized external counsel)." },
 { id: "c2-not-inspected-5yr", chapter: 2, title: "Manager has not been subject to a regulatory inspection in the past five years.", trigger: "No regulatory inspection within the past 5 years", severity: "watch",
 text: "Manager has not been subject to a regulatory inspection in the past five years. A \"modern\" inspection is typically more demanding than in prior years; Alpine flags managers without a recent inspection as there is some risk that \"legacy\" compliance environments fall short of current standards. Managers who previously \"passed\" legacy inspections may be complacent about current requirements." },
 { id: "c2-no-cco", chapter: 2, title: "Manager does not have a dedicated CCO.", trigger: "No dedicated Chief Compliance Officer (role doubled up)", severity: "amber",
 text: "Manager does not have a dedicated CCO. A dedicated Chief Compliance Officer is more likely to bring directly-related professional experience and provides greater assurance that the manager has sufficient bandwidth to address compliance and regulatory matters on a complete and timely basis." },
 { id: "c2-no-compliance-manual", chapter: 2, title: "Manager does not have a written compliance manual.", trigger: "No formal written compliance manual", severity: "red",
 text: "Manager does not have a written compliance manual. Without a formal manual, compliance testing and enforcement will likely not be possible. Absence of a compliance manual suggests, overall, absence of a \"culture of compliance\" within the asset management organization." },
 { id: "c2-litigation-10yr", chapter: 2, title: "Manager, affiliate or employee has been subject of civil or criminal litigation in the past ten years.", trigger: "Civil / criminal litigation within 10 years", severity: "amber",
 text: "Manager, affiliate or employee has been subject of civil or criminal litigation in the past ten years. It would not be unusual for a large organization to accumulate litigation in the normal course of business, and some is a \"nuisance suit\". As a general matter, however, Alpine expects full transparency as to existence of litigation and an appropriate explanation of the facts and circumstances." },
 { id: "c2-no-min-holding", chapter: 2, title: "Personal trades are not subject to a minimum holding period.", trigger: "No minimum holding period on employee personal trades", severity: "amber",
 text: "Personal trades are not subject to a minimum holding period. Alpine prefers a prudent minimum holding period for personal securities trades, so staff cannot \"day trade\" (a distraction from their core function) and to reduce the risk of trading around client portfolios to benefit from knowledge of holdings and anticipated transactions." },
 { id: "c2-no-preclearance", chapter: 2, title: "Personal trading in reportable securities is not subject to pre-clearance from compliance.", trigger: "Personal trades not pre-cleared by compliance", severity: "amber",
 text: "Personal trading in reportable securities is not subject to pre-clearance from compliance. We prefer all employee personal securities transactions to be subject to compliance pre-approval. Risks of weak personal-dealing controls include front-running of fund transactions and situations where investment professionals focus more on their personal portfolios than on managing client assets." },
 { id: "c2-no-direct-stmts", chapter: 2, title: "Employee brokerage statements are not received directly by the compliance department.", trigger: "Compliance does not receive brokerage statements directly", severity: "amber",
 text: "Employee brokerage statements are not received directly by the compliance department. The compliance officer should independently receive employee brokerage statements direct from the brokerage, to cross-check personal trading against pre-cleared transactions. A process where employees submit their own statements is sub-optimal given the risk of dishonest employees manipulating documents." },
 { id: "c2-trade-client-secs", chapter: 2, title: "Employees can trade in securities held in client accounts.", trigger: "Employees permitted to trade securities held in client portfolios", severity: "amber",
 text: "Employees can trade in securities held in client accounts. Certain managers permit trading of securities within the investment universe and held within client portfolios; in such instances controls around conflicts (blackout dates, minimum holding periods) are material to prevent deliberate front-running of client trades by professionals with knowledge of holdings and anticipated transactions." },
 { id: "c2-error-charged-fund", chapter: 2, title: "Negative cost of trading errors can be charged to the Fund.", trigger: "Trade-error losses can be charged to the fund (absent gross negligence)", severity: "amber",
 text: "Negative cost of trading errors can be charged to the Fund. Institutional best practice is for the costs of trade errors to be absorbed by the management company (inadvertent profits retained in the fund). We note, however, that hedge fund offering documents now frequently only require a Manager to reimburse the Fund in the event of an error due to gross negligence, wilful default or fraud." },
 { id: "c2-material-error", chapter: 2, title: "The firm has had a material trading error(s) in the past year (over $10,000).", trigger: "Trade error with cost impact > $10,000 in the past year", severity: "amber",
 text: "The firm has had a material trading error(s) in the past year (over $10,000). Diligence should consider the facts and circumstances of the error; the control failure which enabled it; how the financial impact was remedied; and what changes have been made to ongoing controls to prevent reoccurrence." },
 { id: "c2-expert-networks", chapter: 2, title: "The firm utilizes expert networks.", trigger: "Manager uses expert networks", severity: "watch",
 text: "The firm utilizes expert networks. Expert network firms provide access to industry experts whose information can be material to investee companies. Alpine flags their use and will consider the compliance procedures in place to prevent deliberate or inadvertent access to material non-public information (\"MNPI\")." },
 { id: "c2-expert-not-chaperoned", chapter: 2, title: "Expert network calls are not regularly chaperoned by the compliance department.", trigger: "Expert-network calls not chaperoned by compliance", severity: "amber",
 text: "Expert network calls are not regularly chaperoned by the compliance department. A specific control is for compliance to \"sit in\" on calls between manager employees and external consultants, to ensure the information shared is adequately structured to avoid actual or perceived transfer of MNPI." },
 { id: "c2-no-expert-blackout", chapter: 2, title: "No blackout period with respect to consultation with experts previously employed by a public company.", trigger: "No blackout period for consulting ex-public-company experts", severity: "amber",
 text: "No blackout period with respect to consultation with experts previously employed by a public company. Alpine prefers a minimum \"blackout\" period between the date a consultant leaves a public company (the subject of the consultation) and the first date the consultant becomes available, and flags instances where no such blackout is in place." },
 { id: "c2-admin-no-aml", chapter: 2, title: "The Administrator does not complete AML / KYC verifications.", trigger: "AML / KYC handled in-house rather than by an external administrator", severity: "amber",
 text: "The Administrator does not complete AML / KYC verifications. AML/KYC procedures are typically performed by external administrators with defined procedures and systems. A manager who does not use an administrator must handle KYC in-house, which can increase operational risk as many managers do not have a core competency in this technical compliance area." },
 { id: "c2-external-interests", chapter: 2, title: "Principal(s) have external business interests.", trigger: "Key executives hold for-profit external business interests", severity: "watch",
 text: "Principal(s) have external business interests. Alpine highlights situations where key executive(s) have for-profit external business interests. Potential conflicts should be evaluated (e.g. an interest in a business in competition with the manager or selling services to it / portfolio companies), as should the time commitment involved." },
 { id: "c2-external-directorships", chapter: 2, title: "Principal(s) have external directorship positions.", trigger: "Key principals hold external directorships / board seats", severity: "watch",
 text: "Principal(s) have external directorship positions. Investors should consider (i) the time allocated to external directorships, in case commitments impair focus on the management company, and (ii) potential conflicts of interest arising from external board seats." },
 { id: "c2-private-industry-investments", chapter: 2, title: "Principal(s) have private investments in companies related to the asset management industry.", trigger: "Principals hold investments in firms servicing the asset-management industry", severity: "amber",
 text: "Principal(s) have private investments in companies related to the asset management industry. Such investments (in administrators, compliance consultants, technology firms) should be disclosed and evaluated for conflicts. A situation where an executive owned an interest in a service provider used by the firm's funds could create a material conflict sufficient to generate a \"reject\" assessment." },
 { id: "c2-no-restricted-list", chapter: 2, title: "The firm does not maintain a restricted list.", trigger: "No formal written restricted list maintained", severity: "amber",
 text: "The firm does not maintain a restricted list. A restricted list enables compliance to identify issuers with respect to which the manager may have MNPI, and to prevent purchases/sales in funds, client portfolios and personal accounts. Alpine flags instances in which a manager does not formally maintain a written restricted list." },

 // ── Chapter 3 · Technology, Cybersecurity & Business Resilience ───────────
 { id: "c3-no-it-consultant", chapter: 3, title: "Manager has not appointed a technology consultant.", trigger: "No external IT consultant appointed", severity: "amber",
 text: "Manager has not appointed a technology consultant. External vendors are more likely to have greater technology support resources than a standalone manager, and be more current on IT best practices and threats. Managers who handle all IT in-house may also be subject to material key person risk if key internal IT staff leave." },
 { id: "c3-no-cyber-framework", chapter: 3, title: "The firm has not adopted a third party cybersecurity framework.", trigger: "No third-party cybersecurity framework adopted (NIST/ISO/etc.)", severity: "amber",
 text: "The firm has not adopted a third party cybersecurity framework. The lack of a framework indicates that cyber risk is addressed ad-hoc through piecemeal solutions and no overall vision. The firm has no means to evaluate the risk to its data and its clients' data, and no coherent strategy for mitigating it." },
 { id: "c3-no-dlp", chapter: 3, title: "The firm has not implemented an endpoint data loss prevention solution.", trigger: "No endpoint DLP solution implemented", severity: "amber",
 text: "The firm has not implemented an endpoint data loss prevention solution. Alpine flags instances where the firm cannot monitor, detect and / or stop the transfer of sensitive data from endpoint devices to destinations outside its control (USB drives, personal email, personal cloud). Without DLP, sensitive client data can be siphoned outside the network without the firm's knowledge." },
 { id: "c3-no-network-protection", chapter: 3, title: "The firm has not implemented a baseline network protection solution.", trigger: "No baseline network protection (firewall / antivirus)", severity: "red",
 text: "The firm has not implemented a baseline network protection solution. At a minimum this includes an enterprise-class firewall and antivirus. We also recommend SPAM and web filtering and an intrusion detection system to monitor incoming network traffic." },
 { id: "c3-no-pentest", chapter: 3, title: "The firm does not perform network penetration testing.", trigger: "No network penetration testing performed", severity: "amber",
 text: "The firm does not perform network penetration testing. The lack of visibility over network and system vulnerabilities results in slow and inconsistent adoption of security patches, significantly increasing the opportunity for exploitation and making it a matter of when, not if, the firm's IT systems will be compromised." },
 { id: "c3-bcp-not-tested", chapter: 3, title: "Business Continuity Plan (\"BCP\") is not tested on an annual basis.", trigger: "BCP not tested annually", severity: "amber",
 text: "Business Continuity Plan (\"BCP\") is not tested on an annual basis. The firm's ability to respond to emergencies and continue operations during long-term outages has not been evaluated; the firm will be unable to resume critical business functions in a timely fashion and might not survive disasters it could have prepared for." },

 // ── Chapter 5 · Service Providers, Delegation & Asset Safeguarding ───────
 { id: "c5-noncustodied-5pct", chapter: 5, title: "Portfolio positions exceeding 5% of NAV not held in traditional custody.", trigger: "Non-custodied assets (bank debt, claims) > 5% of NAV", severity: "amber",
 text: "Portfolio positions exceeding 5% of NAV not held in traditional custody. Certain assets may be \"non-custodied\", notably bank debt, trade claims and unusual assets such as aircraft leases, patent rights and royalties, with ownership evidenced by contract. Accounting may be more complex and evidence of existence is typically less robust, with an increased risk of existence fraud." },
 { id: "c5-isda-cross-default", chapter: 5, title: "ISDA Master Agreement(s) includes cross-default provision.", trigger: "ISDA agreements contain a cross-default provision", severity: "amber",
 text: "ISDA Master Agreement(s) includes cross-default provision. Cross-default provisions allow an ISDA to be declared in default if the fund defaults on other ISDAs. Breaching one ISDA can create the ability for all lenders to declare default, thereafter closing credit facilities, seizing collateral etc." },
 { id: "c5-isda-keyperson", chapter: 5, title: "ISDA Master Agreement(s) include key person provision.", trigger: "ISDA agreements contain a key person provision", severity: "amber",
 text: "ISDA Master Agreement(s) include key person provision. A key person provision may allow the ISDA counterparty to call a technical default and demand immediate repayment upon a key person event. This could force a fire sale of assets, harming investor capital and removing the ability for an ordered transition or wind-down following a key person event." },
 { id: "c5-cpty-not-daily", chapter: 5, title: "Counterparty credit risk is not monitored on a daily basis.", trigger: "Counterparty credit risk monitored less than daily", severity: "amber",
 text: "Counterparty credit risk is not monitored on a daily basis. Managers exposed to complex and numerous counterparty relationships should deploy commensurate controls. A manager who fails to formally monitor counterparty risk daily is flagged; such checks are vital for complex strategies and easy to implement for simpler funds." },
 { id: "c5-no-callback", chapter: 5, title: "Transfers exceeding pre-defined thresholds are not subject to a verification call back.", trigger: "Large third-party wires not subject to a verification call back", severity: "amber",
 text: "Transfers exceeding pre-defined thresholds are not subject to a verification call back. Alpine prefers banking counterparties to adopt a verification call back, made to an individual other than the employee who initiated the transfer request. We note that certain banks will not accept liability to enforce this control or describe their procedures to investors." },
 { id: "c5-no-cpty-committee", chapter: 5, title: "The Manager does not have a formal committee overseeing counterparty credit risk.", trigger: "No formal committee oversees counterparty credit risk", severity: "amber",
 text: "The Manager does not have a formal committee overseeing counterparty credit risk. Alpine prefers a formal committee. A smaller manager with one or two counterparty relationships may not have the resources; however, lack of a formal committee would be a material issue for a larger manager. Counterparty committees are proportionately more significant as managers adopt strategies requiring more complex counterparty arrangements." },
 { id: "c5-bank-not-recognized", chapter: 5, title: "Fund has not appointed an industry recognized financial institution for banking services.", trigger: "Banking provider is not a globally recognized institution", severity: "amber",
 text: "Fund has not appointed an industry recognized financial institution for banking services. We note appointment of regional counterparties can be typical for emerging/frontier funds; in all instances investors should consider the rationale and evaluate the stability, regulatory oversight and operational risks of the counterparty. We highlight elevated risk should the bank be a private rather than public company." },

 // ── Chapter 6 · Investment Operations & Portfolio Controls ───────────────
 { id: "c6-no-gl-accounting", chapter: 6, title: "The firm does not maintain a fully featured accounting system with a general ledger.", trigger: "No fully featured (general-ledger) accounting system", severity: "amber",
 text: "The firm does not maintain a fully featured accounting system with a general ledger. A fully featured system maintains internal records of all trades and positions (avoiding complete reliance on an external administrator), supports a cash book and full general-ledger control, enhances the manager's ability to validate the administrator's work, and provides continuity if the fund must rapidly decouple from an administration vendor." },
 { id: "c6-no-cash-tracking", chapter: 6, title: "The Manager does not track cash balances of the Fund.", trigger: "Manager keeps no internal record of cash balances", severity: "amber",
 text: "The Manager does not track cash balances of the Fund. In the absence of a fully featured accounting solution, a Manager should keep a baseline record of all cash transactions and current account balances to validate the work of the third party administrator and identify any inappropriate cash movement." },
 { id: "c6-cross-transactions", chapter: 6, title: "Cross transactions are permitted between funds / client portfolios.", trigger: "Cross transactions between funds / client portfolios permitted", severity: "amber",
 text: "Cross transactions are permitted between funds / client portfolios. Cross transactions can create numerous conflicts: evident valuation issues, and the risk that a manager is artificially supporting the value of an asset by selling it \"internally\". The sale also typically allows the manager to crystallize an incentive fee in the earlier-vintage portfolio when the investment has not been liquidated on an arms-length basis." },
 { id: "c6-no-t1-recon", chapter: 6, title: "The Manager does not complete a full reconciliation of cash, positions, and transactions on T+1.", trigger: "No internal daily (T+1) reconciliation (typically outsourced)", severity: "amber",
 text: "The Manager does not complete a full reconciliation of cash, positions, and transactions on T+1. Managers typically reconcile their own records against custodians, prime brokers and counterparties daily. Alpine flags situations where such reconciliations do not occur, typically because the manager has outsourced the reconciliation or the entire books-and-records process to an external entity." },
 { id: "c6-outsourced-mbo", chapter: 6, title: "The Manager does not maintain internal portfolio position keeping records (outsourced MBO).", trigger: "Middle/back office outsourced; no internal trade/holding records", severity: "amber",
 text: "The Manager does not maintain internal portfolio position keeping records (outsourced MBO). In an \"outsourced middle and back office\" arrangement, responsibility to maintain records of trading activity and holdings is transferred to a third party. We prefer a manager to retain their own internal trade and holding records to avoid undue dependence on a third party." },
 { id: "c6-no-allocation-policy", chapter: 6, title: "Manager does not have a trade allocation policy.", trigger: "No written trade allocation policy", severity: "amber",
 text: "Manager does not have a trade allocation policy. A written policy establishes procedures to allocate trades between multiple eligible accounts and pre-empts conflicts (e.g. allocating \"winning\" trades to higher-fee accounts). Without one, procedures may be ad hoc and compliance testing of allocation decisions will be more difficult or impossible." },
 { id: "c6-proprietary-systems", chapter: 6, title: "The Manager utilizes a proprietary system infrastructure.", trigger: "Manager relies primarily on internally developed software", severity: "watch",
 text: "The Manager utilizes a proprietary system infrastructure. Internally generated software can be better tailored to a manager's needs, but very few managers have the resources to develop and maintain software to the same standards as a third-party software company. Managers may be exposed to key person dependency if key developers leave, and technology may become obsolete over time." },

 // ── Chapter 7 · Valuation, Asset Existence & Investor Reporting ──────────
 { id: "c7-vc-not-majority-nonip", chapter: 7, title: "The valuation committee is not represented by a majority of non-investment professionals.", trigger: "Valuation committee lacks a majority of non-investment members", severity: "amber",
 text: "The valuation committee is not represented by a majority of non-investment professionals. We consider the valuation committee more effective when a majority of members are sourced from back-office control functions, ensuring greater independence and objectivity. A committee with a majority of investment professionals can result in those originating prices (whose compensation is based on performance) controlling the valuation process." },
 { id: "c7-vc-not-each-nav", chapter: 7, title: "The valuation committee is not convened at each NAV calculation date.", trigger: "Valuation committee does not meet at every NAV date", severity: "amber",
 text: "The valuation committee is not convened at each NAV calculation date. Best practice requires the committee to meet and formally review valuation matters as part of the sign-off for each NAV calculation. Alpine flags situations where the committee does not meet as of each NAV date (or meets after the NAV has been determined)." },
 { id: "c7-vc-not-documented", chapter: 7, title: "Valuation committee meetings are not documented.", trigger: "Valuation committee deliberations not minuted", severity: "amber",
 text: "Valuation committee meetings are not documented. Best practice is for meetings to be documented with formal minutes, ensuring deliberations and conclusions are retained, establishing the committee as a formal control component, and providing a documentary trail in the event of a regulatory inspection." },
 { id: "c7-nav-over-15", chapter: 7, title: "NAV timeline exceeding 15 business days.", trigger: "Monthly NAV / statement issuance > 15 business days after month end", severity: "watch",
 text: "NAV timeline exceeding 15 business days. For open-ended hedge funds, Alpine considers 15 business days a reasonable cut-off for the monthly NAV. A lengthy NAV production cycle can indicate accounting complexity, a challenging valuation cycle, or resource constraints at the administrator or the manager's back office." },
 { id: "c7-no-internal-investor-records", chapter: 7, title: "The Manager does not maintain internal investor level accounting records.", trigger: "No internal investor-level accounting records (fully reliant on administrator)", severity: "amber",
 text: "The Manager does not maintain internal investor level accounting records. Alpine flags situations when the manager does not maintain internal, independent records of investor-level accounts; the manager and investors are then entirely dependent on the accuracy of the third-party administrator. Multiple share classes with complex equalization arrangements increase operational complexity and the risk of accounting error, so internal investor-level records can be particularly valuable." },
 { id: "c7-bo-not-review-fmv", chapter: 7, title: "Inputs and assumptions of internal pricing of securities held at fair market value are not reviewed by back office (private securities).", trigger: "Back office does not review front-office FMV pricing of private securities", severity: "amber",
 text: "Inputs and assumptions of internal pricing of securities held at fair market value are not reviewed by back office (private securities). Although pricing models should be \"owned\" by back-office professionals, many firms pass valuation responsibilities to front-office deal teams. Alpine flags managers that have not implemented a control whereby back office reviews proposed valuations, including model assumptions, calculation accuracy, referenced inputs and consistency over time." },
 { id: "c7-ext-agent-not-each-nav", chapter: 7, title: "External valuation agent(s) reports are not updated at each NAV calculation date.", trigger: "Third-party valuation-agent reports not refreshed at every NAV date", severity: "watch",
 text: "External valuation agent(s) reports are not updated at each NAV calculation date. Third-party valuation agents are an important control for hard-to-price instruments. Alpine highlights when reports are not updated at each NAV date, while agreeing the added cost may outweigh the benefit for closed-ended structures where valuations are indicative; investors should consider whether the frequency of external valuations is aligned with the fund's liquidity profile." },
 { id: "c7-admin-accepts-pricing", chapter: 7, title: "The Administrator accepts pricing from the Manager without conducting any verification for all portfolio positions.", trigger: "Administrator accepts manager pricing for all positions without verification", severity: "red",
 text: "The Administrator accepts pricing from the Manager without conducting any verification for all portfolio positions. The administrator plays a critical gatekeeper role. A situation where it accepts pricing without any effort to independently verify significantly increases the risk of valuation fraud and price manipulation: the manager is in effect pricing all instruments themselves without direct external oversight intra-year (oversight typically only provided by the annual GAAP audit)." },
 { id: "c7-agent-reports-not-independent", chapter: 7, title: "Internal pricing supported by external valuation agent(s): Administrator does not receive associated reports independently.", trigger: "External valuation-agent reports not sent to the administrator directly", severity: "amber",
 text: "Internal pricing supported by external valuation agent(s): Administrator does not receive associated reports independently. Best practice calls for all valuation reports prepared by external agents to be sent independently to the administrator, direct from the agents. If reports are forwarded by the manager, information used during NAV preparation could be fictitious or otherwise manipulated by the manager." },
 { id: "c7-admin-not-distribute-audit", chapter: 7, title: "The Administrator is not responsible for the distribution of audited financial statements to investors.", trigger: "Manager (not administrator) distributes audited financials to investors", severity: "amber",
 text: "The Administrator is not responsible for the distribution of audited financial statements to investors. Distribution by the administrator provides greater assurance that the financial statements received by investors are genuine and have not been manipulated by the manager prior to distribution, and provides indirect confirmation of the identity of the auditor." },
 { id: "c7-admin-not-receive-audit-direct", chapter: 7, title: "The Administrator does not receive audited financial statements direct from the auditor.", trigger: "Administrator does not receive the master audited financials directly from the audit firm", severity: "amber",
 text: "The Administrator does not receive audited financial statements direct from the auditor. The administrator should receive the \"master\" copy of the financial statements direct from the audit firm, independent of the manager. This provides confidence that the statements distributed to investors are genuine and have not been manipulated by the manager." },

 // ── Chapter 8 · Manager Transparency & LP Communications ─────────────────
 { id: "c8-bcp-not-available", chapter: 8, title: "BCP is not made available for review.", trigger: "Business Continuity Plan not provided for review", severity: "amber",
 text: "BCP is not made available for review. Investors wish to see that a plan exists and is reasonably detailed and commensurate with the size and scope of the manager's operations. Refusal to provide this document impedes investors' ability to evaluate the manager's IT environment and broader capability to continue operations during a business-interruption event." },
 { id: "c8-admin-agreement-not-available", chapter: 8, title: "Administration agreement is not made available for review.", trigger: "Fund administration agreement not provided for review", severity: "amber",
 text: "Administration agreement is not made available for review. It is important to review the agreement to evaluate the parties, service-level responsibilities (especially responsibility for portfolio valuation), and liability caps. Refusal impedes evaluation of the administrator's services; a manager / administrator who declines also strongly signals that the administrator's \"client\" is the manager, not the fund investor." },
 { id: "c8-compliance-manual-not-available", chapter: 8, title: "Compliance manual not made available for review.", trigger: "Compliance manual not available for review (even onsite)", severity: "amber",
 text: "Compliance manual not made available for review. It is not unusual for managers to decline a soft copy, with the document available only during an onsite visit. Alpine flags circumstances where the compliance manual is not available for review even onsite: absent inspection, Alpine cannot comment on the scope of the document or establish whether individual policies are robust." },
 { id: "c8-cyber-policy-not-available", chapter: 8, title: "Cybersecurity policy is not made available for review.", trigger: "Cyber security policy not provided for review", severity: "amber",
 text: "Cybersecurity policy is not made available for review. The cyber security policy provides important information about the manager's cyber framework and the specific controls implemented to protect the business. Refusal to provide it impedes investors' ability to evaluate the manager's cyber security preparedness." },
 { id: "c8-vc-minutes-not-available", chapter: 8, title: "Valuation committee minutes not made available for review.", trigger: "Sample valuation committee minutes not provided", severity: "amber",
 text: "Valuation committee minutes not made available for review. Access to minutes allows investors to verify whether meetings take place as represented, whether timing matches the NAV cycle, and whether the scope of discussions is comprehensive. Refusal impedes the investor's ability to evaluate controls surrounding the accuracy of security valuation." },
 { id: "c8-asset-transfer-docs-not-available", chapter: 8, title: "Documentation evidencing contractual arrangements over asset transfers not made available for review.", trigger: "Documentation of contractual arrangements over asset transfers not provided", severity: "amber",
 text: "Documentation evidencing contractual arrangements over asset transfers not made available for review. This verification procedure corroborates manager representations on the levels of approval required to execute a transaction and the signing authority of each individual; Alpine flags instances where a manager refuses to make it available." },
 { id: "c8-reg-exit-letter-not-available", chapter: 8, title: "Regulatory inspection(s) exit letter not made available for review.", trigger: "Regulator correspondence / exam exit letters not provided", severity: "amber",
 text: "Regulatory inspection(s) exit letter not made available for review. Regulator documentation is an important evidentiary source. We acknowledge certain regulators impose confidentiality requirements; however, absent sight of correspondence, investors lack assurance that the manager's descriptions of regulatory findings are complete and accurate. Refusal (or inability) to provide exit letters impedes evaluation of the manager's compliance environment." },
];
